/* Container: centred column with side padding. */
.container { width: 100%; margin-inline: auto; padding-inline: var(--s5); }
.container-text { max-width: calc(var(--measure) + 2 * var(--s5)); }
.container-page { max-width: calc(var(--content) + 2 * var(--s5)); }
.container-full { max-width: none; }

/* Block: footer. */
.block-footer { padding-block: var(--s7) var(--s6); border-top: 1px solid var(--foreground); }
.block-footer-top { display: grid; gap: var(--s6); grid-template-columns: 1fr; }
.block-footer-brand { display: flex; flex-direction: column; gap: var(--s2); max-width: 36ch; font-size: var(--text-sm); color: var(--muted); }
.block-footer-name { font-family: var(--font-display); font-weight: 700; color: var(--foreground); font-size: var(--text-lg); }
.block-footer-columns { display: grid; gap: var(--s6); grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); }
.block-footer-heading { font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); font-weight: 500; margin-bottom: var(--s3); }
.block-footer-col ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--s2); font-size: var(--text-sm); }
.block-footer-legal { margin-top: var(--s7); padding-top: var(--s4); border-top: 1px solid var(--rule); font-size: var(--text-xs); color: var(--muted); }
@media (min-width: 860px) { .block-footer-top { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }

